/* ============================================================
   Daylog — local-first life tracker (PWA)
   Data lives in localStorage; optionally syncs to a Google Sheet.
   ============================================================ */

'use strict';

const APP_VERSION = 'v281';   // shown in More ▸ About so you can confirm the build on each device

/* Corruption-proof localStorage reads: one interrupted write (force-kill mid-save is a
   real Android failure mode) must degrade to defaults, never white-screen the boot. */
function safeParse(raw, fb) { if (raw == null) return fb; try { const v = JSON.parse(raw); return v == null ? fb : v; } catch (e) { return fb; } }
/* A parsed store, cached for as long as storage holds exactly the same text. Stats, the Calendar
   and streaks re-read the same store once per day or per habit: with three years of data that
   was 4,400 time segments parsed for every day drawn, 60–70% of a Stats render. The value is
   SHARED between callers, so only code that never changes what it reads may use it — anything
   that edits and saves keeps using DB.entries() / DB.timelog(), which return a fresh copy. */
const _roCache = new Map();
/* Days whose time blocks changed since the last re-sum (see timelogChangedDays). Up here, before
   anything can save the time log, so no early save meets it uninitialised. Kept on disk too
   (dp.tlDirty) until a re-sum takes them: killed in the 1.5 s before the re-sum, the days a delete
   emptied kept their old summary on every phone (a phone that never held the block has no change
   in its log to re-sum on a pull). */
const _tlDirty = new Set();
function tlDirtyKept() { const v = safeParse(localStorage.getItem('dp.tlDirty'), []); return Array.isArray(v) ? v.map(String) : []; }
function roParse(key, fb) {
  const raw = localStorage.getItem(key), c = _roCache.get(key);
  if (c && c.raw === raw) return c.v;
  const v = safeParse(raw, fb);
  _roCache.set(key, { raw, v });
  return v;
}

/* ---------- Config: your habits (from the Daylog form) ----------
   DEFAULT_HABITS is only the starting point — the Customize screen
   (More ▸ Customize) saves your own list to dp.habitcfg, and HABITS
   is rebuilt from it (hidden ones excluded) via reloadCfg(). */
// A lean, universal starter set — new users see just these 4 and add their own
// (or pick more during onboarding). Everything is editable in More ▸ Customize.
const DEFAULT_HABITS = [
  { key: 'workout',     emoji: '💪', label: 'Workout' },
  { key: 'meditation',  emoji: '🧘', label: 'Meditation' },
  { key: 'reading',     emoji: '📖', label: 'Reading' },
  { key: 'healthyFood', emoji: '🥗', label: 'Healthy food', color: '#fb923c' },
];
function habitCfg() { const p = safeParse(localStorage.getItem('dp.habitcfg'), null); return Array.isArray(p) ? p : DEFAULT_HABITS.map(h => Object.assign({}, h)); }
function saveHabitCfg(cfg) { const ok = cfgSave('dp.habitcfg', cfg); reloadCfg(); pushState(); return ok; }
let HABITS = habitCfg().filter(h => !h.hidden);
function reloadCfg() {
  HABITS = habitCfg().filter(h => !h.hidden);
  _goalMap = null; _schedMap = null; _weekFirst = null;                // goal + schedule caches follow the cfg
  try { _wkMemo = new WeakMap(); } catch (e) {}                        // v281: habitWeek counts depend on goals too (try: reloadCfg can run before the let)
  if (typeof actCfg === 'function') TIME_ACTS_ALL = actCfg();
  if (typeof deepCfg === 'function') DEEP_SECTIONS = cookDeep(deepCfg());
}

