  const tm = ev.target.closest('[data-thememode]');
  if (tm) { const s = DB.settings(); s.mode = tm.dataset.thememode; DB.saveSettings(s); applyTheme(); renderCustom(); return; }
  const nh = ev.target.closest('[data-nav-hide]');
