  const cue = state === 'done' ? 'Well done' : state === 'idle' ? 'Ready when you are' : '';
  const sub = state === 'done' ? 'Notice how your body feels now.' : state === 'idle' ? `${pat.label} · tap Start, then follow the circle` : '';
