  if (!mediaBigVideosOk(imgs)) return;
  if (imgs.length > 1) toast(`Adding ${imgs.length}…`);
  const newNote = t.ctx === 'note:new' ? mediaNewNoteId() : null;
  const ctx = newNote ? 'note:' + newNote : t.ctx;
