      // Sheet's to decide whose settings-like stores win, and a fresh phone's 0 let an older Sheet
      // overwrite a restored custom habit list.
      safeSet('dp.touched', String(backupTime(d._at, d.entries, d.timelog)));
      reloadCfg();
