  if (!t) return;
  const d = t.dataset;
  if (d.filmOpen) { filmOpen(d.filmOpen); return; }
  if (d.filmX !== undefined) { try { safeSet('dp.filmSeen', d.filmX); } catch (e) {} const c = t.closest('.film-card'); if (c) c.remove(); buzz(6); return; }
  if (d.filmClose !== undefined) { filmClose(); return; }
